css:
.mktmicro-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #0f1923 0%, #1a2a3a 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    color: #e0e6ed;
}

.mktmicro-sim-header {
    background: linear-gradient(135deg, #1e3a5f 0%, #2c5282 100%);
    color: white;
    padding: 30px;
    border-radius: 16px;
    margin-bottom: 24px;
    box-shadow: 0 8px 24px rgba(0,0,0,0.3);
    text-align: center;
    border: 1px solid rgba(255,255,255,0.1);
}

.mktmicro-sim-header h1 {
    font-size: 1.8rem;
    margin-bottom: 8px;
}

.mktmicro-sim-header p {
    opacity: 0.85;
    margin: 0;
    font-size: 1rem;
}

.mktmicro-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    color: #8899aa;
    margin-bottom: 20px;
}

.mktmicro-sim-briefing {
    background: rgba(30, 58, 95, 0.5);
    border-left: 4px solid #4299e1;
    border-radius: 8px;
    padding: 20px;
    margin-bottom: 24px;
}

.mktmicro-sim-briefing h4 {
    color: #63b3ed;
    margin-bottom: 10px;
    font-size: 1rem;
}

.mktmicro-sim-briefing p {
    margin: 0;
    line-height: 1.6;
    color: #cbd5e0;
}

.mktmicro-sim-section-title {
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 2px;
    color: #63b3ed;
    margin-bottom: 12px;
    padding-left: 4px;
    font-weight: 600;
}

.mktmicro-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}

.mktmicro-sim-status-card {
    background: rgba(255,255,255,0.05);
    border-radius: 12px;
    padding: 18px 14px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.2);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    text-align: center;
    border: 1px solid rgba(255,255,255,0.08);
}

.mktmicro-sim-status-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 6px 16px rgba(0,0,0,0.3);
}

.mktmicro-sim-status-card.mktmicro-money {
    border-top: 3px solid #48bb78;
}

.mktmicro-sim-status-card.mktmicro-capital {
    border-top: 3px solid #ed8936;
}

.mktmicro-sim-label {
    color: #8899aa;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 6px;
}

.mktmicro-sim-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #e2e8f0;
}

.mktmicro-sim-stability-section {
    background: rgba(255,255,255,0.05);
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 24px;
    border: 1px solid rgba(255,255,255,0.08);
}

.mktmicro-sim-progress-wrapper {
    background: rgba(0,0,0,0.3);
    border-radius: 10px;
    height: 20px;
    margin: 10px 0;
    overflow: hidden;
}

.mktmicro-sim-progress-bar {
    height: 100%;
    border-radius: 10px;
    background: linear-gradient(90deg, #e53e3e 0%, #ed8936 30%, #48bb78 70%, #38a169 100%);
    transition: width 0.8s ease;
}

.mktmicro-sim-stability-value {
    font-size: 1.3rem;
    font-weight: 700;
    text-align: right;
    color: #e2e8f0;
}

.mktmicro-sim-qe-badge {
    background: linear-gradient(135deg, #2b6cb0 0%, #3182ce 100%);
    color: white;
    padding: 8px 16px;
    border-radius: 20px;
    display: inline-block;
    margin-bottom: 20px;
    font-weight: 600;
    font-size: 0.85rem;
    animation: mktmicro-pulse 2s infinite;
}

@keyframes mktmicro-pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.7; }
}

.mktmicro-sim-controls {
    background: rgba(255,255,255,0.05);
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 24px;
    border: 1px solid rgba(255,255,255,0.08);
}

.mktmicro-sim-controls h3 {
    color: #e2e8f0;
    margin-bottom: 20px;
    font-size: 1.2rem;
}

.mktmicro-sim-control-group {
    margin-bottom: 16px;
}

.mktmicro-sim-control-group label {
    display: block;
    font-size: 0.85rem;
    color: #a0aec0;
    margin-bottom: 6px;
    font-weight: 500;
}

.mktmicro-sim-container .form-control {
    background: rgba(0,0,0,0.3);
    border: 1px solid rgba(255,255,255,0.15);
    color: #e2e8f0;
    border-radius: 8px;
    padding: 10px 14px;
}

.mktmicro-sim-container .form-control:focus {
    border-color: #4299e1;
    box-shadow: 0 0 0 3px rgba(66,153,225,0.3);
}

.mktmicro-sim-container .btn-primary {
    background: linear-gradient(135deg, #2b6cb0 0%, #3182ce 100%);
    border: none;
    padding: 12px 24px;
    font-weight: 600;
    border-radius: 10px;
    margin-top: 8px;
}

.mktmicro-sim-container .btn-primary:hover {
    background: linear-gradient(135deg, #2c5282 0%, #2b6cb0 100%);
}

.mktmicro-sim-transmission {
    background: rgba(30, 58, 95, 0.3);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 24px;
    border: 1px solid rgba(255,255,255,0.08);
    max-height: 200px;
    overflow-y: auto;
}

.mktmicro-sim-transmission h4 {
    color: #63b3ed;
    margin-bottom: 12px;
    font-size: 1rem;
}

.mktmicro-sim-transmission div {
    font-size: 0.9rem;
    line-height: 1.7;
    color: #a0aec0;
}

.mktmicro-sim-history {
    margin-bottom: 24px;
}

.mktmicro-sim-container .table {
    color: #cbd5e0;
    font-size: 0.85rem;
}

.mktmicro-sim-container .table thead th {
    border-color: rgba(255,255,255,0.1);
    color: #63b3ed;
    font-weight: 600;
}

.mktmicro-sim-container .table td {
    border-color: rgba(255,255,255,0.05);
}

.mktmicro-sim-container .table-striped tbody tr:nth-of-type(odd) {
    background: rgba(255,255,255,0.03);
}

.mktmicro-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
}

.mktmicro-sim-chart {
    background: rgba(255,255,255,0.05);
    border-radius: 12px;
    padding: 16px;
    border: 1px solid rgba(255,255,255,0.08);
    min-height: 280px;
}

@media (max-width: 768px) {
    .mktmicro-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .mktmicro-sim-charts {
        grid-template-columns: 1fr;
    }
    .mktmicro-sim-value {
        font-size: 1.2rem;
    }
}

@media (max-width: 480px) {
    .mktmicro-sim-status-cards {
        grid-template-columns: 1fr;
    }
}

/* --- Completion debrief (v1.1.0, append-only) --- */
.mm-cm { color: #e2e8f0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; padding: 4px; }
.mm-cm-head { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; padding: 18px 20px; background: linear-gradient(135deg, #1e3a5f 0%, #2c5282 100%); border-radius: 14px; border: 1px solid rgba(255,255,255,0.12); margin-bottom: 18px; }
.mm-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #ffffff; }
.mm-cm-score-max { font-size: 1.1rem; font-weight: 600; color: #a0c4e4; margin-left: 2px; }
.mm-cm-meta { display: flex; flex-direction: column; gap: 6px; }
.mm-cm-verdict { font-size: 1.25rem; font-weight: 700; }
.mm-cm-grade { font-size: 0.95rem; color: #cbd5e0; }
.mm-cm-tier-master { color: #48bb78; }
.mm-cm-tier-experienced { color: #63b3ed; }
.mm-cm-tier-competent { color: #f6ad55; }
.mm-cm-tier-novice { color: #fc8181; }
.mm-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 12px; margin-bottom: 18px; }
.mm-cm-kpi { background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 14px 10px; text-align: center; }
.mm-cm-kpi-val { font-size: 1.5rem; font-weight: 700; color: #ffffff; }
.mm-cm-kpi-label { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 1px; color: #9fb0c3; margin-top: 4px; }
.mm-cm-insights { background: rgba(30,58,95,0.4); border-left: 4px solid #4299e1; border-radius: 8px; padding: 14px 18px; }
.mm-cm-insights h4 { color: #63b3ed; margin: 0 0 8px; font-size: 0.95rem; }
.mm-cm-insights ul { margin: 0; padding-left: 20px; }
.mm-cm-insights li { line-height: 1.6; color: #cbd5e0; margin-bottom: 4px; }
.mm-cm-unavailable { color: #cbd5e0; }

