        getChartData(state) {
            var labels = state.domainState.policyRateHistory.map(function(_, i) { return 'P' + (i + 1); });
            return {
                ratesChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.policyRateHistory, label: this._t('policy_rate_label') },
                        { data: state.domainState.fedFundsHistory, label: this._t('col_fed_funds') },
                        { data: state.domainState.repoRateHistory, label: this._t('repo_rate_label') },
                        { data: state.domainState.cpRateHistory, label: this._t('chart_cp') }
                    ]
                },
                stabilityChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.stabilityHistory, label: this._t('stability_label') },
                        { data: state.domainState.corpSpreadHistory.map(function(v) { return v / 10; }), label: this._t('chart_corp_spread') }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var sim = window.mySimulation;
            var t = function(k) { return (sim && sim.t) ? sim.t(k) : k; };
            var ds = sim.state.domainState;
            var sc = this._computeScore(ds);
            var tier = this._tierFor(sc.score);

            var insights = [];
            if (sc.avgStability >= 70) insights.push(t('ins_stability_strong'));
            else insights.push(t('ins_stability_weak'));
            if (sc.equityReturn > 0) insights.push(t('ins_capital_up'));
            else insights.push(t('ins_capital_down'));
            if (sc.stressCount >= 3 && sc.minStab >= 40) insights.push(t('ins_crisis_excellent'));
            if (ds.corpBondSpread > 300) insights.push(t('ins_spreads_wide'));

            return {
                score: sc.score,
                overallScore: sc.score,
                grade: this._gradeFor(sc.score),
                performanceTier: tier,
                performance: t('tier_' + tier),
                performanceLabel: t('tier_' + tier),
                avgStability: Math.round(sc.avgStability),
                finalEquity: sc.finalEquity,
                equityReturn: Math.round(sc.equityReturn * 10) / 10,
                stressEventsManaged: sc.stressCount,
                minStability: sc.minStab,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var sim = window.mySimulation;
            var t = function(k) { return (sim && sim.t) ? sim.t(k) : k; };
            if (!summary || typeof summary.score === 'undefined') {
                return '<div class="mm-cm"><p class="mm-cm-unavailable">' + t('cm_unavailable') + '</p></div>';
            }
            var tier = summary.performanceTier || this._tierFor(summary.score);
            var verdict = t('tier_' + tier);
            var kpi = function(label, val) {
                return '<div class="mm-cm-kpi"><div class="mm-cm-kpi-val">' + val + '</div><div class="mm-cm-kpi-label">' + label + '</div></div>';
            };
            var eq = (summary.equityReturn >= 0 ? '+' : '') + summary.equityReturn + '%';
            var insightsArr = summary.insights || [];
            var insHtml = '';
            for (var i = 0; i < insightsArr.length; i++) {
                insHtml += '<li>' + insightsArr[i] + '</li>';
            }
            var html =
                '<div class="mm-cm">' +
                    '<div class="mm-cm-head">' +
                        '<div class="mm-cm-score">' + summary.score + '<span class="mm-cm-score-max">/100</span></div>' +
                        '<div class="mm-cm-meta">' +
                            '<div class="mm-cm-verdict mm-cm-tier-' + tier + '">' + verdict + '</div>' +
                            '<div class="mm-cm-grade">' + t('cm_grade') + ': <strong>' + summary.grade + '</strong></div>' +
                        '</div>' +
                    '</div>' +
                    '<div class="mm-cm-kpis">' +
                        kpi(t('cm_avg_stability'), summary.avgStability + '/100') +
                        kpi(t('cm_min_stability'), summary.minStability + '/100') +
                        kpi(t('cm_equity_return'), eq) +
                        kpi(t('cm_stress_managed'), summary.stressEventsManaged) +
                    '</div>' +
                    (insHtml ? '<div class="mm-cm-insights"><h4>' + t('cm_insights_heading') + '</h4><ul>' + insHtml + '</ul></div>' : '') +
                '</div>';
            return html;
        }

        getHint(state, results) {
            if (results.systemStability < 30) {
                return window.mySimulation.t('hint_critical');
            }
            if (results.systemStability < 50) {
                return window.mySimulation.t('hint_unstable');
            }
            if (results.corpBondSpread > 400) {
                return window.mySimulation.t('hint_spreads');
            }
            if (results.stressEvent !== 'none') {
                return window.mySimulation.t('hint_stress_injected');
            }
            if (Math.abs(results.rateChange) >= 50) {
                return window.mySimulation.t('hint_aggressive');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'decisions.rateChange', label: 'Rate Change', i18nKey: 'col_rate_change', formatter: function(v) { return (v >= 0 ? '+' : '') + v + ' bps'; } },
                { key: 'results.policyRate', label: 'Policy Rate', i18nKey: 'col_policy_rate', formatter: function(v) { return v.toFixed(2) + '%'; } },
                { key: 'results.fedFundsRate', label: 'Fed Funds', i18nKey: 'col_fed_funds', formatter: function(v) { return v.toFixed(2) + '%'; } },
                { key: 'results.repoRate', label: 'Repo', i18nKey: 'col_repo', formatter: function(v) { return v.toFixed(2) + '%'; } },
                { key: 'results.corpBondSpread', label: 'Corp Spread', i18nKey: 'col_corp_spread', formatter: function(v) { return v + ' bps'; } },
                { key: 'results.equityIndex', label: 'Equity', i18nKey: 'col_equity', formatter: function(v) { return v.toLocaleString(); } },
