        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this._t(round.briefingKey);

            var barEl = document.getElementById('stabilityBar');
            if (barEl && window.mySimulation && window.mySimulation.state) {
                var stab = window.mySimulation.state.domainState.systemStability || 85;
                barEl.style.width = stab + '%';
                barEl.setAttribute('aria-valuenow', stab);
            }

            var qeEl = document.getElementById('qeIndicator');
            if (qeEl && window.mySimulation && window.mySimulation.state) {
                qeEl.style.display = window.mySimulation.state.domainState.qeActive ? 'inline-block' : 'none';
            }

            var _sim = window.mySimulation;
            var ratesC = document.getElementById('ratesChart');
            if (ratesC) ratesC.setAttribute('aria-label', (_sim && _sim.t) ? _sim.t('chart_rates_label') : 'Interest rate transmission chart');
            var stabC = document.getElementById('stabilityChart');
            if (stabC) stabC.setAttribute('aria-label', (_sim && _sim.t) ? _sim.t('chart_stability_label') : 'System stability chart');
        }
